  "code_context": "1: 'use strict';
2: 
3: var hasOwnProperty = require('./object').hasOwnProperty;
4: 
5: /**
6:  * Get a property of a plain object
7:  * Throws an error in case the object is not a plain object or the
8:  * property is not defined on the object itself
9:  * @param {Object} object
10:  * @param {string} prop
11:  * @return {*} Returns the property value when safe
12:  */
13: function getSafeProperty (object, prop) {
14:   // only allow getting properties of a plain object
15:   if (isPlainObject(object)) {
16:     // only allow getting properties defined on the object itself,
17:     // not inherited from it's prototype.
18:     if (hasOwnProperty(object, prop)) {
19:       return object[prop];
20:     }
21: 
22:     if (!(prop in object)) {
23:       // this is a not existing property on a plain object
24:       return undefined;
25:     }
26:   }
27: 
28:   if (typeof object[prop] === 'function' && isSafeMethod(object, prop)) {
29:     throw new Error('Cannot access method "' + prop + '" as a property');
30:   }
31: 
32:   throw new Error('No access to property "' + prop + '"');
33: }
34: 
35: /**
36:  * Set a property on a plain object.
37:  * Throws an error in case the object is not a plain object or the
38:  * property would override an inherited property like .constructor or .toString
39:  * @param {Object} object
40:  * @param {string} prop
41:  * @param {*} value
42:  * @return {*} Returns the value
43:  */
44: // TODO: merge this function into access.js?
45: function setSafeProperty (object, prop, value) {
46:   // only allow setting properties of a plain object
47:   if (isPlainObject(object)) {
48:     // only allow setting properties defined on the object itself,
49:     // not inherited from it's prototype.
50:     if (prop in object) {
51:       // property already exists
52:       // override when the property is defined on the object itself.
53:       // don't allow overriding inherited properties like .constructor or .toString
54:       if (hasOwnProperty(object, prop)) {
55:         return object[prop] = value;
56:       }
57:     }
58:     else {
59:       // this is a new property, that's just ok
60:       return object[prop] = value;
61:     }
62:   }
63: 
64:   throw new Error('No access to property "' + prop + '"');
65: }
