67: /**
68:  * Test whether a property is safe to use for an object.
69:  * For example .toString and .constructor are not safe
70:  * @param {string} prop
71:  * @return {boolean} Returns true when safe
72:  */
73: function isSafeProperty (object, prop) {
74:   if (!object || typeof object !== 'object') {
75:     return false;
76:   }
77:   // UNSAFE: ghosted
78:   // e.g length
79:   if (hasOwnProperty(object, prop) && (prop in object.__proto__)) {
80:     return false;
81:   }
82:   // SAFE: whitelisted
83:   // e.g length
84:   if (hasOwnProperty(safeNativeProperties, prop)) {
85:     return true;
86:   }
87:   // UNSAFE: inherited from Object prototype
88:   // e.g constructor
89:   if (hasOwnProperty(Object.prototype, prop)) {
90:     return false;
91:   }
92:   // UNSAFE: inherited from Function prototype
93:   // e.g call, apply
94:   if (hasOwnProperty(Function.prototype, prop)) {
95:     return false;
96:   }
97:   return true;
98: }
99: 
100: /**
101:  * Validate whether a method is safe.
102:  * Throws an error when that's not the case.
103:  * @param {Object} object
104:  * @param {string} method
105:  */
106: // TODO: merge this function into assign.js?
107: function validateSafeMethod (object, method) {
108:   if (!isSafeMethod(object, method)) {
109:     throw new Error('No access to method "' + method + '"');
110:   }
111: }
112: 
113: /**
114:  * Check whether a method is safe.
115:  * Throws an error when that's not the case (for example for `constructor`).
116:  * @param {Object} object
117:  * @param {string} method
118:  * @return {boolean} Returns true when safe, false otherwise
119:  */
120: function isSafeMethod (object, method) {
121:   if (!object || typeof object[method] !== 'function') {
122:     return false;
123:   }
124:   // UNSAFE: ghosted
125:   // e.g toString
126:   if (hasOwnProperty(object, method) && (method in object.__proto__)) {
127:     return false;
128:   }
129:   // SAFE: whitelisted
130:   // e.g toString
131:   if (hasOwnProperty(safeNativeMethods, method)) {
132:     return true;
133:   }
134:   // UNSAFE: inherited from Object prototype
135:   // e.g constructor
136:   if (hasOwnProperty(Object.prototype, method)) {
137:     return false;
138:   }
139:   // UNSAFE: inherited from Function prototype
140:   // e.g call, apply
141:   if (hasOwnProperty(Function.prototype, method)) {
142:     return false;
143:   }
144:   return true;
145: }
146: 
147: function isPlainObject (object) {
148:   return typeof object === 'object' && object && object.constructor === Object;
149: }
150: 
151: var safeNativeProperties = {
152:   length: true
153: };
154: 
155: var safeNativeMethods = {
156:   toString: true,
157:   valueOf: true,
158:   toLocaleString: true
159: };
160: 
161: exports.getSafeProperty = getSafeProperty;
162: exports.setSafeProperty = setSafeProperty;
163: exports.isSafeProperty = isSafeProperty;
164: exports.validateSafeMethod = validateSafeMethod;
165: exports.isSafeMethod = isSafeMethod;
166: exports.isPlainObject = isPlainObject;",
  "source_summary": "The function validates property names for objects used in math expression parsing and evaluation. The 'object' parameter is typically a plain object (scope, math namespace, or object node properties) that may contain user-defined or built-in properties. The 'prop' parameter is a string property name that may come from parsed expression syntax (e.g., object property access like 'obj.constructor').",
  "sink_summary": "The validation result (true/false) controls whether property access is allowed in getSafeProperty/setSafeProperty and object node compilation. If unsafe, an error is thrown preventing access to dangerous inherited properties like constructor, toString, call, apply, or ghosted properties.",
  "guard_summary": "The function implements multiple security checks: 1) Rejects non-objects; 2) Rejects 'ghosted' properties (own property that also exists in prototype); 3) Allows whitelisted native properties (e.g., 'length'); 4) Rejects properties inherited from Object.prototype; 5) Rejects properties inherited from Function.prototype. These controls aim to prevent prototype pollution and access to dangerous inherited methods.",
